document.querySelectorAll("[data-copy]").forEach((e=>{e.addEventListener("click",(async()=>{const t=e.textContent;try{await navigator.clipboard.writeText(e.dataset.copy),e.textContent="Copiado!"}catch{e.textContent="Selecione e copie"}setTimeout((()=>e.textContent=t),2e3)}))}));const e=document.querySelectorAll(".reveal");if("IntersectionObserver"in window&&e.length){document.documentElement.classList.add("js");const t=new IntersectionObserver((e=>{e.forEach((e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),t.unobserve(e.target))}))}),{threshold:.12});e.forEach((e=>t.observe(e)))}